const P={};
P['']=()=>`<section class="hero"><div class="tx"><span class="tag">Knowledge • Intelligence • Discovery</span><h1>Welcome to CREED Neurovascular Framework</h1><p>A learning platform that joins neuroscience, AI and exam preparation so every learner can <b>Learn Beyond Boundaries</b>. Study with lessons, quizzes, an AI tutor, flashcards and a focus timer, all in one place.</p><a class="btn" href="#/login">Get started</a><a class="btn o" href="#/about">Read the introduction</a></div><div class="ph"><img src="assets/me1.jpg" alt="Founder of CREED"></div></section>
<section><h2>A Brief Introduction to the CREED Neurovascular Framework</h2><p>CREED stands for Knowledge, Intelligence and Discovery. The Neurovascular Framework starts from how the brain actually learns: neurons work only as well as the blood supply that feeds them, so focus, rest, nutrition and good study habits all shape results. CREED turns that idea into a practical platform: organised lessons, interactive quizzes and examinations, an AI learning assistant, spaced-revision flashcards, a Pomodoro timer, progress tracking, a student community and certificates. It serves secondary school candidates (WAEC, JAMB, NECO, GCE, IELTS), university students and lecturers, and grows in five stages from foundation to an advanced global ecosystem.</p></section>
<section><h2>Features</h2><div class="grid">${[['📚','Learning dashboard','Organised lessons, topics, notes and materials.','dashboard'],['📝','Interactive quizzes','Questions, scores and instant feedback.','quiz'],['⏱️','Study tools','Pomodoro timer, statistics, scientific calculator.','tools'],['🤖','AI tutor','Teaches, answers questions, makes flashcards.','tutor'],['🗂️','Flashcards & notes','Save, revise and export study material.','tools'],['🎓','Certificates','Earn a certificate at 70% or more.','quiz'],['💬','Community','Discuss with students and lecturers.','community'],['🎬','Reels','Short learning and motivation clips.','reels']].map(f=>`<a class="card" style="text-decoration:none;color:inherit" href="#/${f[3]}"><div class="i">${f[0]}</div><h3>${f[1]}</h3><p>${f[2]}</p></a>`).join('')}</div></section>`;
P.about=()=>`<section><h2>About CREED</h2><div class="grid"><div class="rl"><img src="assets/me3.jpg" alt="Founder reading"></div><div><p>CREED Neurovascular Framework is a learning ecosystem built to make quality education, brain science and exam success accessible to every student, wherever they are.</p><p><br>Our logo shows a brain wearing a graduation cap, rising from an open book: knowledge, intelligence and discovery working as one.</p></div></div><h2 style="margin-top:30px">Roadmap</h2><div class="grid">${[['Stage 1 — Foundation','Brand identity, website, user registration, business profiles and basic assessments.'],['Stage 2 — Diagnostic intelligence','Business Stability Index, entrepreneur assessments, problem identification and diagnostic reports.'],['Stage 3 — AI solutions','Personalised action plans, root-cause analysis, recommendations and progress tracking.'],['Stage 4 — Industry intelligence','Industry assessments, benchmarking and a professional expert network.'],['Stage 5 — Advanced ecosystem','Corporate dashboards, predictive risk monitoring, institutional partnerships and international expansion.']].map(s=>`<div class="card stage"><h3>${s[0]}</h3><p>${s[1]}</p></div>`).join('')}</div></section>`;
