P.login=()=>user()?`<section class="wrap"><h2>Hi ${esc(user().name)}</h2><button class="btn s" onclick="S('creed_session',null);nav()">Log out</button></section>`:`<section class="wrap"><h2>Student Login / Register</h2><div class="grid"><div class="card"><h3>Register</h3><input id="rn" placeholder="Full name"><input id="re" type="email" placeholder="Email"><input id="rp" type="password" placeholder="Password"><button class="btn s" onclick="reg()">Create account</button></div><div class="card"><h3>Login</h3><input id="le" type="email" placeholder="Email"><input id="lp" type="password" placeholder="Password"><button class="btn s" onclick="login()">Login</button></div></div><p style="font-size:13px">Accounts are stored in this browser only; a server database is needed for real multi-device accounts.</p></section>`;
P.dashboard=()=>{if(!user())return`<section class="wrap"><h2>Dashboard</h2><p>Please <a href="#/login">log in</a> first.</p></section>`;const pr=L('creed_prog',{}),dn=Object.keys(pr.lessons||{}).length,sc=pr.scores||[],st=L('creed_pom',0),pc=Math.round(dn/Object.keys(TOPICS).length*100);
return`<section><h2>Welcome, ${esc(user().name)}</h2><div class="grid"><div class="card"><h3>Lessons</h3><div class="bar"><i style="width:${pc}%"></i></div><p>${dn}/${Object.keys(TOPICS).length} complete</p></div><div class="card"><h3>Focus sessions</h3><div class="big">${st}</div></div><div class="card"><h3>Flashcards</h3><div class="big">${L('creed_fc',[]).length}</div></div></div><h3 style="margin:20px 0 8px">Quiz results & certificates</h3>${sc.map((s,i)=>`<div class="card" style="margin:6px 0">${esc(s.s)}: ${s.p}% ${s.p>=70?`<button class="btn s" onclick="cert(${i})">Certificate</button>`:''}</div>`).join('')||'<p>No quizzes yet.</p>'}<h3 style="margin:20px 0 8px">Lessons</h3><div class="grid">${Object.keys(TOPICS).map(k=>`<div class="card">${(pr.lessons||{})[k]?'✅':'⬜'} ${k}</div>`).join('')}</div></section>`};
function nav(){let h=(location.hash.replace('#/','')||'');if(!P[h])h='';$('#app').innerHTML=(G(h)||P[h]());$('#nav').innerHTML=navHTML(h);$('#nav').classList.remove('open');window.scrollTo(0,0);if(h=='library')lib('');if(h=='community')cl();if(h=='tools')showfc();if(h=='reels')rinit();rtop();if(h=='calculator'&&user())cinit();if(h=='pomodoro'){pdraw();pstats()}}
