function reg(){const u=L('creed_users',{}),e=$('#re').value.trim().toLowerCase();if(!e||!$('#rn').value||$('#rp').value.length<4)return alert('Fill all fields (password 4+ chars).');if(u[e])return alert('Email already registered.');u[e]={name:$('#rn').value,pw:btoa($('#rp').value)};S('creed_users',u);S('creed_session',{name:u[e].name,email:e});location.hash='#/dashboard';}
