function done(k){const p=L('creed_prog',{});p.lessons=p.lessons||{};p.lessons[k]=1;S('creed_prog',p);alert('Lesson saved to your progress.');}
function lib(q){$('#ll').innerHTML=LIB.filter(x=>x.toLowerCase().includes(q.toLowerCase())).map(x=>`<div class="card">📖 ${x}</div>`).join('')||'<p>No results.</p>';}
function ask(){const q=$('#q').value.trim();if(!q)return;const ch=$('#ch');ch.innerHTML+=`<div class="m u">${esc(q)}</div>`;$('#q').value='';let a,l=q.toLowerCase();const all=Object.entries(TOPICS);
if(/flashcard/.test(l)){const hit=all.filter(([k,v])=>l.includes(k.toLowerCase().split(' ')[0])||(v.toLowerCase().includes(l.split(' ').pop())));const src=hit.length?hit:all.slice(0,2),fc=L('creed_fc',[]);src.forEach(([k,v])=>v.split('. ').forEach(s=>fc.push({q:'About '+k+': key fact?',a:s.replace(/\.$/,'')})));S('creed_fc',fc);a='I created '+src.reduce((n,[k,v])=>n+v.split('. ').length,0)+' flashcards. Open Study Tools to revise them.';}
else{const w=l.split(/\W+/).filter(x=>x.length>3);let best=null,sc=0;all.forEach(([k,v])=>{const n=w.filter(x=>(k+v).toLowerCase().includes(x)).length;if(n>sc){sc=n;best=[k,v]}});a=best?`<b>${best[0]}</b>: ${best[1]}`:'I do not have that topic yet. Try: neuron, synapse, hippocampus, cerebellum, nervous system or neurovascular coupling.';}
ch.innerHTML+=`<div class="m a">${a}</div>`;ch.scrollTop=1e5;}
let tI,tS=1500,run=0;function pom(g){clearInterval(tI);run=0;if(!g){tS=1500;sh();return}tI=setInterval(()=>{tS--;sh();if(tS<=0){clearInterval(tI);S('creed_pom',L('creed_pom',0)+1);tS=300;$('#ps').textContent='Session done! Take a 5-minute break.';sh()}},1000)}
function sh(){const t=$('#tm');if(t)t.textContent=String(Math.floor(tS/60)).padStart(2,'0')+':'+String(tS%60).padStart(2,'0');$('#ps')&&!$('#ps').textContent&&0;}
function cb(k){const d=$('#cd');if(k=='C')d.value='';else if(k=='⌫')d.value=d.value.slice(0,-1);else if(k=='='){try{let x=d.value.replace(/√\(/g,'Math.sqrt(').replace(/π/g,'Math.PI').replace(/\be\b/g,'Math.E').replace(/\^/g,'**').replace(/sin\(/g,'S(').replace(/cos\(/g,'C(').replace(/tan\(/g,'T(').replace(/log\(/g,'Math.log10(');if(/[^0-9+\-*\/.()%A-Za-z,*]/.test(x))throw 0;const S_=a=>Math.sin(a*Math.PI/180),C_=a=>Math.cos(a*Math.PI/180),T_=a=>Math.tan(a*Math.PI/180);d.value=String(+new Function('S','C','T','return '+x)(S_,C_,T_).toFixed(10))}catch(e){d.value='Error'}}else d.value+=k;}
let fi=0,fb=0;function showfc(){const f=L('creed_fc',[]),v=$('#fcv');if(v)v.textContent=f.length?(fb?f[fi%f.length].a:f[fi%f.length].q):'No cards yet';}
function addfc(){const q=$('#fq').value,a=$('#fa').value;if(!q||!a)return;const f=L('creed_fc',[]);f.push({q,a});S('creed_fc',f);$('#fq').value=$('#fa').value='';showfc();}
