function exp(){const t=L('creed_fc',[]).map(c=>c.q+'\t'+c.a).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([t]));a.download='creed-flashcards.txt';a.click();}
let Q,qi,qs;function startQ(){const s=$('#qs').value;Q=QZ[s];Q.s=s;qi=0;qs=0;nq();}
function nq(){const b=$('#qb');if(qi>=Q.length){const p=Math.round(qs/Q.length*100),pr=L('creed_prog',{});pr.scores=pr.scores||[];pr.scores.push({s:Q.s,p,n:(user()||{}).name||'Student',d:new Date().toDateString()});S('creed_prog',pr);b.innerHTML=`<div class="card"><h3>Score: ${qs}/${Q.length} (${p}%)</h3><p>${p>=70?'Great! Certificate available on your dashboard.':'Keep practising!'}</p></div>`;return}
const q=Q[qi];b.innerHTML=`<div class="card"><p><b>${qi+1}/${Q.length}.</b> ${q[0]}</p>${q[2].map(o=>`<button class="opt" onclick="pick(this,'${o.replace(/'/g,"\\'")}')">${o}</button>`).join('')}</div>`;}
