function rid(r){return r.url||r.img}
function rdraw(){const lk=L('creed_likes',{}),sv=L('creed_saved',{}),f=document.getElementById('rf');if(!f)return;let list=RV.filter(r=>RF=='All'||(RF=='Saved'?sv[rid(r)]:r.cat==RF));
f.innerHTML=list.map((r,i)=>{const p=r.url?rparse(r.url):null,k=rid(r).replace(/'/g,"\\'");return`<div class="rl2" data-i="${i}"><div class="vid">${r.img?`<img src="${r.img}" alt="">`:p?(p.t=='v'?`<video data-src="${p.s}" controls loop playsinline muted></video>`:`<iframe data-src="${p.s}" allow="autoplay;encrypted-media;fullscreen" allowfullscreen></iframe>`):'<p>Unsupported link</p>'}</div><div class="side"><button onclick="rtog('creed_likes','${k}')">${lk[rid(r)]?'❤️':'🤍'}<small>Like</small></button><button onclick="rtog('creed_saved','${k}')">${sv[rid(r)]?'🔖':'📑'}<small>Save</small></button><button onclick="rshare('${k}')">🔗<small>Share</small></button></div><div class="cap"><span class="tag">${r.cat||'Learning'}</span><b>${esc(r.title||'')}</b></div></div>`}).join('')||'<p>No reels here yet.</p>';
RO&&RO.disconnect();RO=new IntersectionObserver(es=>es.forEach(e=>{const m=e.target.querySelector('iframe,video');if(!m)return;if(e.isIntersecting){let s=m.dataset.src;if(m.tagName=='IFRAME'&&/youtube|tiktok/.test(s))s+=(s.includes('?')?'&':'?')+'autoplay=1&mute=1';m.src=s;if(m.play)m.play().catch(()=>{})}else{if(m.pause)m.pause();m.removeAttribute('src');if(m.tagName=='IFRAME')m.src='about:blank'}}),{threshold:.7});f.querySelectorAll('.rl2').forEach(x=>RO.observe(x))}
