const tr=x=>cDeg?x*Math.PI/180:x,ar=x=>cDeg?x*180/Math.PI:x;
const CF={sin:x=>Math.sin(tr(x)),cos:x=>Math.cos(tr(x)),tan:x=>Math.tan(tr(x)),asin:x=>ar(Math.asin(x)),acos:x=>ar(Math.acos(x)),atan:x=>ar(Math.atan(x)),sinh:Math.sinh,cosh:Math.cosh,tanh:Math.tanh,ln:Math.log,log:Math.log10,sqrt:Math.sqrt,cbrt:Math.cbrt,abs:Math.abs,exp:Math.exp,inv:x=>1/x,
fact:n=>{if(n<0||n%1||n>170)throw 0;let r=1;for(let i=2;i<=n;i++)r*=i;return r},nPr:(n,r)=>CF.fact(n)/CF.fact(n-r),nCr:(n,r)=>CF.fact(n)/(CF.fact(r)*CF.fact(n-r)),round:Math.round,floor:Math.floor,ceil:Math.ceil};
function ceval(s){let x=s.replace(/(\d+)!/g,'fact($1)').replace(/π/g,'PI_').replace(/√/g,'sqrt').replace(/\^/g,'**').replace(/×/g,'*').replace(/÷/g,'/').replace(/−/g,'-').replace(/\bmod\b/g,'%').replace(/(?<![\d.a-zA-Z_])e(?![a-zA-Z_(\d+-])/g,'E_');
x=x.replace(/(\d|\)|PI_|E_|ans)\s*(?=(?!e[+-]?\d)[a-zA-Z(])/g,'$1*');if(!/^[\d\s+\-*\/%().,a-zA-Z_]*$/.test(x))throw 0;
const names=Object.keys(CF),ok=[...names,'PI_','E_','ans'],ids=x.replace(/\d+\.?\d*(e[+-]?\d+)?/gi,'0').match(/[a-zA-Z_]+/g)||[];if(ids.some(i=>!ok.includes(i)))throw 0;
const r=new Function(...names,'PI_','E_','ans','return '+x)(...names.map(n=>CF[n]),Math.PI,Math.E,cAns);if(typeof r!='number'||!isFinite(r))throw 0;return r}
const cfmt=r=>String(+r.toPrecision(12));
