P.calculator=()=>`<section class="wrap" style="max-width:640px"><h2>🧮 Scientific Calculator</h2><div class="card"><input id="cd" class="cdisp" placeholder="0" autocomplete="off" oninput="clive()" onkeydown="if(event.key=='Enter')ck(47)"><div id="cr" class="cres"></div><small id="cs"></small><div class="sc">${CK.map((k,i)=>`<button class="${k[1]=='='?'e':/^[\d.]$/.test(k[1])?'n':''}" id="k${i}" onclick="ck(${i})">${k[0]}</button>`).join('')}</div><small>Type with your keyboard too. Supports 2π, 3(4+1), 5!, 1e3 and nested functions.</small></div><div class="card" style="margin-top:14px"><h3>History</h3><div id="ch2"></div></div></section>`;
function cin(t){const i=$('#cd'),a=i.selectionStart??i.value.length,b=i.selectionEnd??a;i.value=i.value.slice(0,a)+t+i.value.slice(b);i.focus();i.setSelectionRange(a+t.length,a+t.length);clive()}
function cstat(){const s=$('#cs'),k=$('#k0');if(s)s.textContent=(cDeg?'DEG':'RAD')+(cMem?'  ·  M = '+cfmt(cMem):'');if(k)k.textContent=cDeg?'Deg':'Rad'}
function clive(){const r=$('#cr'),v=$('#cd').value;if(!r)return;try{r.textContent=v.trim()?'= '+cfmt(ceval(v)):''}catch(e){r.textContent=''}}
function ck(i){const v=CK[i][1],d=$('#cd');if(v=='m'){cDeg=!cDeg;cDeg=+cDeg;cstat();clive()}else if(v=='mc'){cMem=0;cstat()}else if(v=='mr')cin(cfmt(cMem));else if(v=='m+'||v=='m-'){let n;try{n=ceval(d.value)}catch(e){n=cAns}cMem+=v=='m+'?n:-n;cstat()}
else if(v=='bs'){d.value=d.value.slice(0,-1);clive()}else if(v=='ac'){d.value='';$('#cr').textContent=''}
else if(v=='='){try{const r=ceval(d.value);cH.unshift({e:d.value,r:cfmt(r)});cH=cH.slice(0,15);S('creed_chist',cH);cAns=r;d.value=cfmt(r);$('#cr').textContent='';chist()}catch(e){$('#cr').textContent='Error: check your expression'}}else cin(v)}
function chist(){const h=$('#ch2');if(h)h.innerHTML=cH.map(x=>`<div style="cursor:pointer;padding:4px 0;border-bottom:1px solid #e4ecff" onclick="cin('${x.r}')">${esc(x.e)} = <b>${x.r}</b></div>`).join('')||'<p>No calculations yet.</p>'}
