let pS=L('creed_pset',{f:25,s:5,l:15}),pMode='f',pEnd=0,pLeft=pS.f*60,pRun=0,pI,pCnt=0;
P.pomodoro=()=>`<section class="wrap" style="max-width:640px;text-align:center"><h2>⏱ Pomodoro Timer</h2><div class="card"><div class="tabs">${[['f','Focus'],['s','Short break'],['l','Long break']].map(m=>`<button class="chip pm" data-m="${m[0]}" onclick="pset('${m[0]}')">${m[1]}</button>`).join('')}</div>
<svg viewBox="0 0 200 200" width="250"><circle cx="100" cy="100" r="90" fill="none" stroke="#dde6ff" stroke-width="12"/><circle id="pr" cx="100" cy="100" r="90" fill="none" stroke="#0b5fff" stroke-width="12" stroke-linecap="round" stroke-dasharray="565.5" stroke-dashoffset="0" transform="rotate(-90 100 100)" style="transition:stroke-dashoffset .3s"/><text id="pt" x="100" y="112" text-anchor="middle" font-size="40" font-weight="800" fill="#0a1440">25:00</text></svg>
<input id="ptk" placeholder="What are you studying? (e.g. Neurobiology)" style="text-align:center"><div><button class="btn s" id="pb" onclick="pstart()">▶ Start</button><button class="btn o" onclick="pset(pMode)">↺ Reset</button><button class="btn o" onclick="pskip()">⏭ Skip</button></div></div>
<div class="grid" style="margin-top:14px;text-align:left"><div class="card"><h3>Settings (minutes)</h3>Focus<input id="sf" type="number" min="1" max="120" value="${pS.f}">Short break<input id="ss" type="number" min="1" max="60" value="${pS.s}">Long break<input id="sl" type="number" min="1" max="60" value="${pS.l}"><button class="btn s" onclick="psave()">Save</button></div><div class="card" id="pst"></div></div></section>`;
function pdraw(){const g=id=>document.getElementById(id),t=pS[pMode]*60,tx=String(Math.floor(pLeft/60)).padStart(2,'0')+':'+String(pLeft%60).padStart(2,'0');g('pt')&&(g('pt').textContent=tx);g('pr')&&g('pr').setAttribute('stroke-dashoffset',565.5*(1-pLeft/t));g('pb')&&(g('pb').textContent=pRun?'⏸ Pause':'▶ Start');document.querySelectorAll('.pm').forEach(b=>b.classList.toggle('on',b.dataset.m==pMode));document.title=pRun?tx+' · CREED':'CREED Neurovascular Framework | Learn Beyond Boundaries'}
function pset(m){pMode=m;pRun=0;clearInterval(pI);pLeft=pS[m]*60;pdraw()}
function pstart(){if(pRun){pRun=0;clearInterval(pI)}else{pEnd=Date.now()+pLeft*1000;pRun=1;pI=setInterval(ptick,250);window.Notification&&Notification.permission=='default'&&Notification.requestPermission()}pdraw()}
function ptick(){pLeft=Math.max(0,Math.round((pEnd-Date.now())/1000));if(pLeft<=0)pfin(1);else pdraw()}
function pskip(){pfin(0)}
function pfin(real){clearInterval(pI);pRun=0;let n='f';if(pMode=='f'){if(real){const lg=L('creed_plog',{}),d=new Date().toLocaleDateString('en-CA');lg[d]=lg[d]||{m:0,n:0};lg[d].m+=pS.f;lg[d].n++;S('creed_plog',lg);S('creed_pom',L('creed_pom',0)+1);pCnt++}n=pCnt&&pCnt%4==0?'l':'s'}
if(real){pbeep();const msg=pMode=='f'?'Focus session complete. Take a break!':'Break over. Time to focus!';window.Notification&&Notification.permission=='granted'&&new Notification('CREED Pomodoro',{body:msg});const m=document.getElementById('ptk');}pset(n);pstats()}
function pbeep(){try{const a=new(window.AudioContext||window.webkitAudioContext)();[0,.3,.6].forEach(t=>{const o=a.createOscillator(),g=a.createGain();o.frequency.value=880;o.connect(g);g.connect(a.destination);g.gain.setValueAtTime(.2,a.currentTime+t);o.start(a.currentTime+t);o.stop(a.currentTime+t+.2)})}catch(e){}}
