function pstats(){const e=document.getElementById('pst');if(!e)return;const lg=L('creed_plog',{}),days=[...Array(7)].map((_,i)=>{const d=new Date(Date.now()-(6-i)*864e5);return[d.toLocaleDateString('en-CA'),d.toLocaleDateString('en',{weekday:'short'})]}),t=lg[days[6][0]]||{m:0,n:0},mx=Math.max(30,...days.map(d=>(lg[d[0]]||{m:0}).m));
e.innerHTML=`<h3>Study statistics</h3><p>Today: <b>${t.n}</b> sessions · <b>${t.m}</b> min</p><p>All time: <b>${L('creed_pom',0)}</b> sessions</p><div class="wk">${days.map(d=>{const m=(lg[d[0]]||{m:0}).m;return`<div><i style="height:${m/mx*70}px"></i><small>${d[1]}</small></div>`}).join('')}</div>`}
